import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import Header from './Header';
import Sidebar from './Sidebar';
import FinancialTicker from './FinancialTicker';

const Layout = ({ children }) => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const location = useLocation();

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [location.pathname]);

  return (
    <div className="min-h-screen bg-background text-on-background noise-overlay font-body">
      <div className="gradient-mesh" />
      
      <Header onMenuClick={() => setIsSidebarOpen(true)} />
      
      <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} />

      <main className="relative pt-20 pb-24 px-6 md:ml-80 transition-all duration-300">
        <div className="max-w-7xl mx-auto py-8">
          {children}
        </div>
      </main>

      <FinancialTicker />
    </div>
  );
};

export default Layout;
