import React from 'react';
import { useSelector } from 'react-redux';
import { selectAllTransactions } from '../features/transactions/transactionSlice';
import { Download, FileJson, Table, CheckCircle, ChevronRight } from 'lucide-react';

const ExportPage = () => {
  const transactions = useSelector(selectAllTransactions);

  const downloadFile = (content, fileName, contentType) => {
    const a = document.createElement("a");
    const file = new Blob([content], { type: contentType });
    a.href = URL.createObjectURL(file);
    a.download = fileName;
    a.click();
    URL.revokeObjectURL(a.href);
  };

  const exportJSON = () => {
    const content = JSON.stringify(transactions, null, 2);
    downloadFile(content, `ledger_export_${new Date().toISOString().split('T')[0]}.json`, "application/json");
  };

  const exportCSV = () => {
    const headers = ["ID", "Date", "Description", "Merchant", "Category", "Amount"];
    const rows = transactions.map(t => [
      t.id,
      t.date,
      `"${t.description.replace(/"/g, '""')}"`,
      `"${(t.merchant || '').replace(/"/g, '""')}"`,
      t.category,
      t.amount
    ]);
    const content = [headers, ...rows].map(e => e.join(",")).join("\n");
    downloadFile(content, `ledger_export_${new Date().toISOString().split('T')[0]}.csv`, "text/csv");
  };

  return (
    <div className="max-w-5xl mx-auto space-y-12 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
          <h2 className="font-headline text-4xl font-bold tracking-tight text-on-background mb-2">Export Data</h2>
          <p className="text-zinc-500 max-w-xl font-body">Download your financial records for offline auditing and tax compliance. All files are encrypted at rest.</p>
        </div>
        <div className="glass-card border border-outline-variant/15 p-6 rounded-xl flex items-center gap-6">
          <div className="text-right">
            <p className="text-[10px] font-label uppercase text-zinc-500 tracking-tighter">Current Batch</p>
            <p className="text-2xl font-label tabular font-bold text-primary">{transactions.length} records</p>
          </div>
          <div className="h-10 w-[1px] bg-outline-variant/20" />
          <div className="text-right">
            <p className="text-[10px] font-label uppercase text-zinc-500 tracking-tighter">Format</p>
            <p className="text-2xl font-label tabular font-bold text-secondary">JSON/CSV</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-stretch">
        {/* JSON Export Card */}
        <section className="glass-card rounded-xl p-8 flex flex-col relative overflow-hidden group">
          <div className="absolute top-0 left-0 w-1/4 h-[2px] bg-primary" />
          <div className="flex items-center gap-6 mb-8">
            <div className="w-14 h-14 rounded-full bg-primary/10 flex items-center justify-center border border-primary/20">
              <FileJson className="w-6 h-6 text-primary" />
            </div>
            <div>
              <h3 className="font-headline text-xl font-bold">Export as JSON</h3>
              <p className="text-xs font-label text-zinc-500 uppercase tracking-widest">application/json</p>
            </div>
          </div>
          <div className="flex-grow">
            <div className="bg-surface-container-lowest rounded-lg p-4 font-mono text-[11px] leading-relaxed border border-outline-variant/10 mb-8 max-h-[160px] overflow-hidden opacity-60">
              <pre className="text-primary">{`{
  "id": "TX-${Math.floor(Math.random()*100000)}",
  "amount": ${transactions[0]?.amount || 0},
  "category": "${transactions[0]?.category || 'Capital Assets'}"
}`}</pre>
            </div>
          </div>
          <button 
            onClick={exportJSON}
            className="w-full bg-gradient-to-br from-primary to-primary-container text-on-primary font-label font-bold uppercase tracking-widest text-xs py-4 rounded-sm flex items-center justify-center gap-2 hover:opacity-90 active:scale-[0.98] transition-all shadow-lg"
          >
            <Download className="w-4 h-4" />
            Download JSON
          </button>
        </section>

        {/* CSV Export Card */}
        <section className="glass-card rounded-xl p-8 flex flex-col relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-1/4 h-[2px] bg-secondary" />
          <div className="flex items-center gap-6 mb-8">
            <div className="w-14 h-14 rounded-full bg-secondary/10 flex items-center justify-center border border-secondary/20">
              <Table className="w-6 h-6 text-secondary" />
            </div>
            <div>
              <h3 className="font-headline text-xl font-bold">Export as CSV</h3>
              <p className="text-xs font-label text-zinc-500 uppercase tracking-widest">text/csv</p>
            </div>
          </div>
          <div className="flex-grow space-y-4 mb-8">
            <p className="text-[10px] font-label text-zinc-500 uppercase tracking-widest mb-4">Included Columns (6)</p>
            <div className="grid grid-cols-2 gap-3">
              {['Transaction ID', 'Date', 'Description', 'Merchant', 'Category', 'Amount'].map(col => (
                <div key={col} className="flex items-center gap-2 text-on-surface-variant text-sm border-b border-outline-variant/5 pb-2">
                  <CheckCircle className="w-3 h-3 text-secondary" />
                  <span className="font-body text-[10px] uppercase tracking-wider">{col}</span>
                </div>
              ))}
            </div>
          </div>
          <button 
            onClick={exportCSV}
            className="w-full bg-secondary text-on-secondary py-4 rounded-sm font-label font-bold uppercase tracking-widest text-xs flex items-center justify-center gap-2 hover:opacity-90 active:scale-[0.98] transition-all shadow-lg"
          >
            <Download className="w-4 h-4" />
            Download CSV
          </button>
        </section>
      </div>

      {/* Additional Options */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {['Verification', 'Filtering', 'Compression'].map((label, idx) => (
          <div key={label} className="glass-card p-6 rounded border border-outline-variant/10 group cursor-pointer hover:bg-surface-container-low transition-colors">
            <h4 className="text-[10px] font-label text-zinc-500 uppercase tracking-widest mb-4">{label}</h4>
            <div className="flex items-center justify-between">
              <span className="text-sm font-label uppercase tracking-widest text-on-surface">
                {idx === 0 ? 'SHA-256 Checksum' : idx === 1 ? 'All Batches' : 'Standard'}
              </span>
              <ChevronRight className="w-4 h-4 group-hover:translate-x-1 transition-transform text-primary" />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ExportPage;
