import { BrowserRouter as Router, Route, Routes, Navigate } from "react-router-dom";
import { useEffect } from "react";
import { useDispatch } from "react-redux";
import { setTransactions } from "./features/transactions/transactionSlice";
import { mockTransactions } from "./data/mockData";

import Layout from "./components/common/Layout";
import HomePage from "./pages/HomePage";
import TransactionsPage from "./pages/TransactionsPage";
import AnalyticsPage from "./pages/AnalyticsPage";
import GuidePage from "./pages/GuidePage";
import ImportPage from "./pages/ImportPage";
import ExportPage from "./pages/ExportPage";
import { UIProvider } from "./context/UIContext";
import AddExpenseModal from "./features/expenses/AddExpenseModal/AddExpenseModal";

function App() {
  const dispatch = useDispatch();

  useEffect(() => {
    // Initialize store with mock data
    dispatch(setTransactions(mockTransactions));
  }, [dispatch]);

  return (
    <UIProvider>
      <Router basename="/ExpenseTracker">
        <Layout>
          <Routes>
            <Route path="/" element={<Navigate to="/home" replace />} />
            <Route path="/home" element={<HomePage />} />
            <Route path="/expenses" element={<TransactionsPage />} />
            <Route path="/analytics" element={<AnalyticsPage />} />
            <Route path="/guide" element={<GuidePage />} />
            <Route path="/import" element={<ImportPage />} />
            <Route path="/export" element={<ExportPage />} />
          </Routes>
        </Layout>
        <AddExpenseModal />
      </Router>
    </UIProvider>
  );
}

export default App;
