import React, { useState } from 'react';
import { Menu, Search, User, X } from 'lucide-react';
import { Link, useLocation } from 'react-router-dom';

const Header = ({ onMenuClick }) => {
  const location = useLocation();
  
  const navLinks = [
    { name: 'Home', path: '/' },
    { name: 'Expenses', path: '/expenses' },
    { name: 'Analytics', path: '/analytics' },
    { name: 'Guide', path: '/guide' },
  ];

  return (
    <header className="fixed top-0 right-0 left-0 md:left-80 z-50 bg-zinc-950/60 backdrop-blur-xl border-b border-outline-variant/15 shadow-[0_20px_50px_rgba(0,0,0,0.5)] flex items-center justify-between px-6 h-16 transition-all duration-300">
      <div className="flex items-center gap-4">
        <button 
          onClick={onMenuClick}
          className="p-1 hover:bg-surface-container-highest rounded-lg transition-colors active:scale-95 md:hidden"
        >
          <Menu className="w-6 h-6 text-primary" />
        </button>
        <h1 className="text-xl font-headline text-primary font-bold tracking-tight">₹ Ledger</h1>
      </div>
      
      <div className="hidden lg:flex items-center gap-8 font-label text-[10px] uppercase tracking-[0.2em]">
        {navLinks.map((link) => {
          const isActive = location.pathname === link.path;
          return (
            <Link 
              key={link.name}
              to={link.path} 
              className={`transition-colors ${isActive ? 'text-primary font-bold' : 'text-zinc-400 hover:text-on-background'}`}
            >
              {link.name}
            </Link>
          );
        })}
      </div>

      <div className="flex items-center gap-4">
        <div className="w-8 h-8 rounded-full border border-primary/20 overflow-hidden shrink-0 shadow-lg">
          <img 
            src={`${process.env.PUBLIC_URL}/assets/image.png`}
            alt="User Profile"
            className="w-full h-full object-cover"
          />
        </div>
      </div>
    </header>
  );
};

export default Header;
