import React, { useState, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { selectAllTransactions } from '../features/transactions/transactionSlice';
import { ChevronLeft, ChevronRight, TrendingUp, TrendingDown, Lightbulb, Calendar, PieChart as PieChartIcon, BarChart3 } from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ArcElement,
  PointElement,
  LineElement,
} from 'chart.js';
import { Bar, Doughnut } from 'react-chartjs-2';

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ArcElement,
  PointElement,
  LineElement
);

const monthNames = ["January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

const AnalyticsPage = () => {
  const transactions = useSelector(selectAllTransactions);

  const [viewMode, setViewMode] = useState('month'); // 'month', 'quarter', 'year'
  const [selectedDate, setSelectedDate] = useState(new Date('2026-03-01'));

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      if (viewMode === 'month') {
        return d.getMonth() === selectedDate.getMonth() && d.getFullYear() === selectedDate.getFullYear();
      } else if (viewMode === 'quarter') {
        const qSelected = Math.floor(selectedDate.getMonth() / 3);
        const qTxn = Math.floor(d.getMonth() / 3);
        return qSelected === qTxn && d.getFullYear() === selectedDate.getFullYear();
      } else {
        return d.getFullYear() === selectedDate.getFullYear();
      }
    });
  }, [transactions, selectedDate, viewMode]);

  const stats = useMemo(() => {
    const categories = {};
    let total = 0;
    let peak = 0;
    filteredTransactions.forEach(t => {
      if (t.amount < 0) {
        const abs = Math.abs(t.amount);
        categories[t.category] = (categories[t.category] || 0) + abs;
        total += abs;
        if (abs > peak) peak = abs;
      }
    });
    return { categories, total, peak };
  }, [filteredTransactions]);

  const handlePrev = () => {
    const newDate = new Date(selectedDate);
    if (viewMode === 'month') newDate.setMonth(newDate.getMonth() - 1);
    else if (viewMode === 'quarter') newDate.setMonth(newDate.getMonth() - 3);
    else newDate.setFullYear(newDate.getFullYear() - 1);
    setSelectedDate(newDate);
  };

  const handleNext = () => {
    const newDate = new Date(selectedDate);
    if (viewMode === 'month') newDate.setMonth(newDate.getMonth() + 1);
    else if (viewMode === 'quarter') newDate.setMonth(newDate.getMonth() + 3);
    else newDate.setFullYear(newDate.getFullYear() + 1);
    setSelectedDate(newDate);
  };

  // Chart Data preparation
  const mainChartData = useMemo(() => {
    let labels = [];
    let values = [];

    if (viewMode === 'month') {
      const days = new Date(selectedDate.getFullYear(), selectedDate.getMonth() + 1, 0).getDate();
      labels = Array.from({ length: days }, (_, i) => `${i + 1}`);
      values = Array(days).fill(0);
      filteredTransactions.forEach(t => {
        if (t.amount < 0) values[new Date(t.date).getDate() - 1] += Math.abs(t.amount);
      });
    } else if (viewMode === 'quarter') {
      const startMonth = Math.floor(selectedDate.getMonth() / 3) * 3;
      labels = [monthNames[startMonth], monthNames[startMonth + 1], monthNames[startMonth + 2]];
      values = [0, 0, 0];
      filteredTransactions.forEach(t => {
        if (t.amount < 0) values[new Date(t.date).getMonth() - startMonth] += Math.abs(t.amount);
      });
    } else {
      labels = monthNames.map(m => m.substring(0, 3));
      values = Array(12).fill(0);
      filteredTransactions.forEach(t => {
        if (t.amount < 0) values[new Date(t.date).getMonth()] += Math.abs(t.amount);
      });
    }

    return {
      labels,
      datasets: [{
        label: 'Spending Velocity (₹)',
        data: values,
        backgroundColor: 'rgba(201, 168, 76, 0.6)',
        borderColor: 'rgba(201, 168, 76, 1)',
        borderWidth: 1,
        borderRadius: 4,
        hoverBackgroundColor: 'rgba(201, 168, 76, 0.8)',
      }]
    };
  }, [filteredTransactions, viewMode, selectedDate]);

  const doughnutData = useMemo(() => {
    const labels = Object.keys(stats.categories);
    const data = Object.values(stats.categories);
    return {
      labels,
      datasets: [{
        data,
        backgroundColor: [
          'rgba(201, 168, 76, 0.7)',
          'rgba(123, 106, 224, 0.7)',
          'rgba(76, 175, 80, 0.7)',
          'rgba(244, 67, 54, 0.7)',
          'rgba(255, 152, 0, 0.7)',
          'rgba(0, 188, 212, 0.7)',
        ],
        borderWidth: 0,
        hoverOffset: 15,
      }]
    };
  }, [stats]);

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      tooltip: {
        backgroundColor: '#121212',
        titleFont: { family: 'Space Grotesk', size: 12 },
        bodyFont: { family: 'Inter', size: 11 },
        padding: 12,
        cornerRadius: 8,
        borderColor: 'rgba(255,255,255,0.1)',
        borderWidth: 1,
      }
    },
    scales: {
      y: {
        beginAtZero: true,
        grid: { color: 'rgba(255,255,255,0.03)' },
        ticks: { color: '#666', font: { size: 9 }, callback: (v) => `₹${v / 1000}k` }
      },
      x: {
        grid: { display: false },
        ticks: { color: '#666', font: { size: 9 } }
      }
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700 pb-12">
      {/* Header & Filters */}
      <section className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-1 bg-surface-container-low p-2 rounded-xl border border-outline-variant/10 shadow-inner">
            <button onClick={handlePrev} className="p-2 hover:bg-surface-container-high rounded-lg transition-all text-primary active:scale-90">
              <ChevronLeft className="w-5 h-5" />
            </button>
            <div className="w-64 text-center shrink-0 py-2">
              <h2 className="text-2xl font-headline font-bold text-on-surface tracking-tight leading-tight mb-1">
                {viewMode === 'month' && monthNames[selectedDate.getMonth()]}
                {viewMode === 'quarter' && `Quarter ${Math.floor(selectedDate.getMonth() / 3) + 1}`}
                {viewMode === 'year' && 'Fiscal Year'}
              </h2>
              <span className="text-[10px] font-label text-zinc-500 uppercase tracking-widest">{selectedDate.getFullYear()}</span>
            </div>
            <button onClick={handleNext} className="p-2 hover:bg-surface-container-high rounded-lg transition-all text-primary active:scale-90">
              <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        </div>

        <div className="flex bg-surface-container-low p-1.5 rounded-xl border border-outline-variant/10 shadow-lg">
          {['month', 'quarter', 'year'].map(mode => (
            <button
              key={mode}
              onClick={() => { console.log('Setting viewMode to:', mode); setViewMode(mode); }}
              className={`
                px-6 py-2.5 text-[10px] font-label uppercase tracking-widest rounded-lg transition-all
                ${viewMode === mode ? 'bg-primary text-on-primary font-bold shadow-2xl scale-105 z-10' : 'text-zinc-500 hover:text-primary hover:bg-primary/5'}
              `}
            >
              {mode}
            </button>
          ))}
        </div>
      </section>

      {/* Summary Bento */}
      <section className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Total Outflow', val: `₹${stats.total.toLocaleString('en-IN')}`, icon: TrendingDown, color: 'text-error' },
          { label: 'Peak Transaction', val: `₹${stats.peak.toLocaleString('en-IN')}`, icon: BarChart3, color: 'text-primary' },
          { label: 'Top Category', val: Object.keys(stats.categories).sort((a, b) => stats.categories[b] - stats.categories[a])[0] || 'N/A', icon: PieChartIcon, color: 'text-tertiary' },
          { label: 'Volume', val: filteredTransactions.length, icon: Calendar, color: 'text-secondary' }
        ].map((item, i) => (
          <div key={i} className="p-6 rounded-2xl glass-card border-l-4 border-l-primary/40 hover:border-l-primary transition-all group relative overflow-hidden flex flex-col justify-between min-h-[140px]">
            <div className="absolute inset-0 pointer-events-none text-current">
              <item.icon className="absolute right-[-1] top-[1.2] translate-x-4 translate-y-4 w-24 h-24 rotate-12 opacity-15 group-hover:opacity-30 transition-all" />
            </div>
            <div className="relative z-10 w-full mb-1">
              <p className="text-[10px] font-label text-zinc-500 uppercase tracking-widest mb-1">{item.label}</p>
              <p className={`text-2xl lg:text-3xl font-headline font-bold ${item.color} tabular tracking-tighter leading-loose pb-2`}>{item.val}</p>
            </div>
          </div>
        ))}
      </section>

      {/* Charts section */}
      <section className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-8 p-8 rounded-2xl bg-surface-container-low border border-outline-variant/10 shadow-xl min-h-[400px] flex flex-col">
          <div className="flex justify-between items-center mb-8">
            <div className="flex items-center gap-3">
              <div className="w-1.5 h-1.5 rounded-full bg-primary" />
              <h3 className="font-headline text-sm font-bold uppercase tracking-[0.2em] text-zinc-400">Spending Velocity</h3>
            </div>
            <span className="text-[10px] font-label text-zinc-600 bg-zinc-900 px-3 py-1 rounded-full uppercase tracking-widest">{viewMode}ly active</span>
          </div>
          <div className="flex-1 relative">
            <Bar data={mainChartData} options={chartOptions} />
          </div>
        </div>

        <div className="lg:col-span-4 p-8 rounded-2xl bg-surface-container-low border border-outline-variant/10 shadow-xl min-h-[400px] flex flex-col">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-1.5 h-1.5 rounded-full bg-tertiary" />
            <h3 className="font-headline text-sm font-bold uppercase tracking-[0.2em] text-zinc-400">Asset Mix</h3>
          </div>
          <div className="flex-1 relative mb-6 flex items-center justify-center min-h-[220px]">
            <div className="relative w-full max-w-[200px] aspect-square mx-auto">
              <Doughnut
                data={doughnutData}
                options={{
                  ...chartOptions,
                  plugins: { ...chartOptions.plugins, legend: { display: false } },
                  scales: { x: { display: false }, y: { display: false } },
                  cutout: '75%',
                  maintainAspectRatio: true
                }}
              />
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center justify-center pointer-events-none w-full text-center">
                <p className="text-[10px] font-label text-zinc-500 uppercase tracking-widest mb-0.5 mt-2">Total</p>
                <p className="text-xl font-headline font-bold text-on-surface leading-tight">₹{(stats.total / 1000).toFixed(1)}k</p>
              </div>
            </div>
          </div>
          <div className="space-y-3 overflow-y-auto max-h-32 pr-2 custom-scrollbar">
            {Object.entries(stats.categories).sort((a, b) => b[1] - a[1]).slice(0, 4).map(([cat, val], idx) => (
              <div key={cat} className="flex items-center justify-between text-[11px] font-label group cursor-default">
                <div className="flex items-center gap-2 text-zinc-400 group-hover:text-primary transition-colors flex-1 min-w-0">
                  <div className={`w-1.5 h-1.5 rounded-full shrink-0 ${['bg-primary', 'bg-tertiary', 'bg-secondary', 'bg-outline'][idx] || 'bg-zinc-700'}`} />
                  <span className="uppercase tracking-widest truncate">{cat}</span>
                </div>
                <span className="text-zinc-500 tabular">₹{val.toLocaleString('en-IN')}</span>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Observations */}
      <section className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="p-6 rounded-2xl bg-gradient-to-br from-primary/5 to-transparent border border-primary/10 flex gap-5 hover:border-primary/20 transition-all">
          <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center shrink-0">
            <Lightbulb className="w-6 h-6 text-primary" />
          </div>
          <div>
            <h4 className="text-xs font-bold uppercase tracking-[0.2em] text-primary mb-2">Spending Insight</h4>
            <p className="text-xs text-zinc-400 leading-relaxed font-body">
              Your largest outflow this period was in <span className="text-on-surface font-bold italic">"{Object.keys(stats.categories).sort((a, b) => stats.categories[b] - stats.categories[a])[0] || 'N/A'}"</span>.
              Efficiency is trending {stats.total > 50000 ? 'slightly high' : 'within optimal range'} for the current velocity.
            </p>
          </div>
        </div>
        <div className="p-6 rounded-2xl bg-gradient-to-br from-tertiary/5 to-transparent border border-tertiary/10 flex gap-5 hover:border-tertiary/20 transition-all">
          <div className="w-12 h-12 rounded-xl bg-tertiary/10 flex items-center justify-center shrink-0">
            <TrendingUp className="w-6 h-6 text-tertiary" />
          </div>
          <div>
            <h4 className="text-xs font-bold uppercase tracking-[0.2em] text-tertiary mb-2">Burn Projections</h4>
            <p className="text-xs text-zinc-400 leading-relaxed font-body">
              Based on current momentum, we project a {viewMode}ly settlement of roughly ₹{(stats.total * 1.05).toLocaleString('en-IN', { maximumFractionDigits: 0 })}.
              Consider reallocation to stabilize momentum.
            </p>
          </div>
        </div>
      </section>
    </div>
  );
};

export default AnalyticsPage;
