import React, { useState, useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { addTransaction } from '../../transactions/transactionSlice';
import { CATEGORIES } from '../../../data/mockData';
import { Plus, X, ChevronDown } from 'lucide-react';
import { useUI } from '../../../context/UIContext';
import { useLocation } from 'react-router-dom';

const AddExpenseModal = () => {
  const { isExpenseModalOpen, setIsExpenseModalOpen } = useUI();
  const dispatch = useDispatch();
  const location = useLocation();
  
  const [formData, setFormData] = useState({
    description: '',
    amount: '',
    category: CATEGORIES[0],
    date: new Date().toISOString().split('T')[0],
    merchant: '',
  });

  useEffect(() => {
    if (isExpenseModalOpen) {
      setIsExpenseModalOpen(false);
    }
  }, [location.pathname]); // eslint-disable-line react-hooks/exhaustive-deps

  if (!isExpenseModalOpen) return null;

  const handleAddSubmit = (e) => {
    e.preventDefault();
    if (!formData.description || !formData.amount) return;

    const newTxn = {
      id: Date.now().toString(),
      ...formData,
      amount: parseFloat(formData.amount) * (formData.category === 'Income' ? 1 : -1),
    };

    dispatch(addTransaction(newTxn));
    setIsExpenseModalOpen(false);
    setFormData({
      description: '',
      amount: '',
      category: CATEGORIES[0],
      date: new Date().toISOString().split('T')[0],
      merchant: '',
    });
  };

  return (
    <div className="fixed inset-0 flex items-center justify-center p-4 sm:p-8" style={{ zIndex: 99999 }}>
      <div 
        className="absolute inset-0 bg-black/95 backdrop-blur-2xl cursor-pointer" 
        onClick={() => setIsExpenseModalOpen(false)} 
      />
      <div className="relative bg-surface-container-lowest border border-outline-variant/30 w-[90vw] sm:w-[400px] h-auto max-h-[90vh] p-6 sm:p-8 rounded-2xl shadow-2xl animate-in zoom-in-95 fade-in duration-300 flex flex-col overflow-y-auto custom-scrollbar overflow-x-hidden">
        {/* Decorative background element */}
        <div className="absolute top-0 right-0 w-48 h-48 bg-primary/10 rounded-full blur-3xl pointer-events-none -translate-y-1/2 translate-x-1/2" />
        
        <button 
          onClick={() => setIsExpenseModalOpen(false)} 
          className="absolute top-6 right-6 text-zinc-500 hover:text-primary transition-colors z-[100]"
        >
          <X className="w-5 h-5" />
        </button>
        
        <div className="mb-8 relative z-10 shrink-0">
          <div className="flex items-center gap-2 mb-2">
            <div className="w-8 h-[1px] bg-primary" />
            <span className="text-[10px] uppercase tracking-[0.3em] font-label text-primary font-bold">New Entry</span>
          </div>
          <h2 className="text-3xl font-headline font-bold text-on-surface tracking-tighter">Log Transaction</h2>
        </div>
        
        <form onSubmit={handleAddSubmit} className="space-y-6 relative z-10 flex flex-col flex-1 pb-4">
          <div className="space-y-4">
            <div className="space-y-2">
              <label className="text-[10px] font-label uppercase text-zinc-500 ml-1 tracking-widest">Memo / Description</label>
              <input 
                type="text" 
                required
                className="w-full bg-surface-container-low border border-outline-variant/15 p-3 rounded-lg text-sm outline-none focus:border-primary transition-all text-on-surface"
                placeholder="e.g. Monthly Rent"
                value={formData.description}
                onChange={e => setFormData({...formData, description: e.target.value})}
              />
            </div>
            
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-[10px] font-label uppercase text-zinc-500 ml-1 tracking-widest">Value (₹)</label>
                <input 
                  type="number" 
                  required
                  step="0.01"
                  className="w-full bg-surface-container-low border border-outline-variant/15 p-3 rounded-lg text-sm outline-none focus:border-primary transition-all text-on-surface tabular cursor-text"
                  placeholder="0.00"
                  value={formData.amount}
                  onChange={e => setFormData({...formData, amount: e.target.value})}
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-label uppercase text-zinc-500 ml-1 tracking-widest">Asset Class</label>
                <div className="relative">
                  <select 
                    className="w-full bg-surface-container-low border border-outline-variant/15 p-3 rounded-lg text-sm outline-none focus:border-primary transition-all appearance-none text-on-surface cursor-pointer"
                    value={formData.category}
                    onChange={e => setFormData({...formData, category: e.target.value})}
                  >
                    {CATEGORIES.map(cat => (
                      <option key={cat} value={cat}>{cat}</option>
                    ))}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500 pointer-events-none" />
                </div>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-[10px] font-label uppercase text-zinc-500 ml-1 tracking-widest">Entity / Merchant</label>
                <input 
                  type="text" 
                  className="w-full bg-surface-container-low border border-outline-variant/15 p-3 rounded-lg text-sm outline-none focus:border-primary transition-all text-on-surface"
                  placeholder="e.g. Amazon"
                  value={formData.merchant}
                  onChange={e => setFormData({...formData, merchant: e.target.value})}
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-label uppercase text-zinc-500 ml-1 tracking-widest">Date</label>
                <input 
                  type="date" 
                  className="w-full bg-surface-container-low border border-outline-variant/15 p-3 rounded-lg text-xs outline-none focus:border-primary transition-all text-on-surface cursor-pointer"
                  value={formData.date}
                  onChange={e => setFormData({...formData, date: e.target.value})}
                />
              </div>
            </div>
          </div>

          <button 
            type="submit"
            className="w-full bg-primary text-on-primary font-label font-bold py-4 rounded-xl shadow-[0_4px_20px_rgba(0,0,0,0.3)] hover:shadow-primary/30 active:scale-[0.98] transition-all uppercase tracking-[0.2em] text-xs mt-auto flex items-center justify-center gap-2 group shrink-0"
          >
            <span>Authorize Transaction</span>
            <Plus className="w-4 h-4 group-hover:rotate-90 transition-transform" />
          </button>
        </form>
      </div>
    </div>
  );
};

export default AddExpenseModal;
