import React from 'react';
import { Home, LayoutGrid, BarChart3, BookOpen, Download, Upload, User, X } from 'lucide-react';
import { Link, useLocation } from 'react-router-dom';

const Sidebar = ({ isOpen, onClose }) => {
  const location = useLocation();

  const navItems = [
    { name: 'Home', icon: Home, path: '/' },
    { name: 'Expenses', icon: LayoutGrid, path: '/expenses' },
    { name: 'Analytics', icon: BarChart3, path: '/analytics' },
    { name: 'Guide', icon: BookOpen, path: '/guide' },
    { name: 'Import', icon: Upload, path: '/import' },
    { name: 'Export', icon: Download, path: '/export' },
  ];

  return (
    <>
      {/* Mobile Overlay */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[60] md:hidden"
          onClick={onClose}
        />
      )}

      <aside className={`
        fixed top-0 bottom-0 left-0 w-80 bg-surface-container-lowest border-r border-outline-variant/10 
        transform transition-transform duration-300 z-[70] pt-20 pb-8 px-4 flex flex-col
        ${isOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
      `}>
        <div className="flex items-center justify-between mb-10 px-4 md:hidden">
          <h2 className="text-primary font-headline text-lg font-bold">Ledger Elite</h2>
          <button onClick={onClose} className="text-zinc-400 hover:text-on-background">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="hidden md:block mb-10 px-4">
          <h2 className="text-primary font-headline text-lg font-bold">Ledger Elite</h2>
          <p className="text-zinc-500 text-[10px] uppercase tracking-widest font-label mt-1">Terminal Session Active</p>
        </div>

        <nav className="flex-1 space-y-2">
          {navItems.map((item) => {
            const isActive = location.pathname === item.path;
            return (
              <Link
                key={item.name}
                to={item.path}
                onClick={() => onClose()}
                className={`
                  flex items-center gap-4 px-4 py-3 rounded-lg transition-all group
                  ${isActive 
                    ? 'text-primary bg-surface-container-highest border-l-2 border-primary' 
                    : 'text-zinc-500 hover:text-zinc-300 hover:bg-surface-container-low'}
                `}
              >
                <item.icon className={`w-5 h-5 ${isActive ? 'text-primary' : 'group-hover:text-primary'}`} />
                <span className="font-label uppercase tracking-widest text-xs">{item.name}</span>
              </Link>
            );
          })}
        </nav>

        <div className="mt-auto px-4">
          <div className="p-4 rounded-xl glass-card flex items-center gap-3">
              <div className="w-10 h-10 rounded-full border border-primary/20 overflow-hidden shrink-0">
                <img 
                  src={`${process.env.PUBLIC_URL}/assets/image.png`}
                  alt="User Profile"
                  className="w-full h-full object-cover"
                />
              </div>
              <div className="overflow-hidden flex-1">
                <p className="text-xs font-bold truncate text-on-surface">Shivansh Soni</p>
              </div>
          </div>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;
