import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  status: 'idle',
  error: null,
};

const transactionSlice = createSlice({
  name: 'transactions',
  initialState,
  reducers: {
    setTransactions: (state, action) => {
      state.items = action.payload;
    },
    addTransaction: (state, action) => {
      state.items.unshift(action.payload);
    },
    deleteTransaction: (state, action) => {
      state.items = state.items.filter(item => item.id !== action.payload);
    },
    updateTransaction: (state, action) => {
      const index = state.items.findIndex(item => item.id === action.payload.id);
      if (index !== -1) {
        state.items[index] = action.payload;
      }
    },
  },
});

export const { setTransactions, addTransaction, deleteTransaction, updateTransaction } = transactionSlice.actions;

export const selectAllTransactions = (state) => state.transactions.items;
export const selectTotalBalance = (state) => state.transactions.items.reduce((acc, item) => acc + item.amount, 0);

export default transactionSlice.reducer;
